style.css:
/* ROBLOX NEON GREEN BACKGROUND */

html, body {
    background-color: #050a07 !important;
    color: #eaffed !important;
}

body {
    background-image:
        radial-gradient(
            circle at 20% 30%,
            rgba(0,255,65,0.2),
            transparent 45%
        ),
        radial-gradient(
            circle at 80% 70%,
            rgba(0,180,50,0.2),
            transparent 45%
        ),
        linear-gradient(
            135deg,
            #020603,
            #07150b,
            #020603
        ) !important;

    background-size: 300% 300% !important;
    animation: neonMove 12s ease infinite !important;
}

@keyframes neonMove {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}
